 function spawnWave(){let count=wave+2;enemies=[];for(let i=0;i<count;i++){let p;do{p={x:2+Math.random()*11,y:2+Math.random()*11,hp:1,alive:true,attack:0};}while(map[Math.floor(p.y)][Math.floor(p.x)]!=='0'||Math.hypot(p.x-player.x,p.y-player.y)<4);enemies.push(p)}document.getElementById('waveNum').textContent=String(wave).padStart(2,'0');updateKills()}
 function cell(x,y){let v=map[Math.floor(y)]?.[Math.floor(x)];return v&&v!=='0'?Number(v):0}
 function wallColor(t,u,side,dist){let base=t===1?[104,91,69]:t===2?[108,47,38]:[57,86,79];let mortar=Math.floor((u*8)%1*64)<4;let lum=(side?.72:1)*(Math.max(.4,1-dist/13));if(mortar)lum*=.58;let stripe=Math.floor(u*8)%2?1:.86;return `rgb(${base.map(v=>Math.max(0,Math.floor(v*lum*stripe))).join(',')})`}
 function render(){let img=ctx.createImageData(W,H),d=img.data;for(let y=0;y<H/2;y++){let shade=.12+y/(H/2)*.14;for(let x=0;x<W;x++){let i=(y*W+x)*4;d[i]=Math.floor(20+shade*40);d[i+1]=Math.floor(22+shade*43);d[i+2]=Math.floor(25+shade*48);d[i+3]=255}}for(let y=H/2;y<H;y++){let p=y-H/2+1;for(let x=0;x<W;x++){let ray=player.a+Math.atan((x-W/2)/(W*.66)),row=H/2+(H*.5)/p,dist=(.5*H)/p;let wx=player.x+Math.cos(ray)*dist,wy=player.y+Math.sin(ray)*dist;let checker=(Math.floor(wx*2)+Math.floor(wy*2))%2===0?1:.78;let fog=Math.max(.22,1-dist/15),i=(y*W+x)*4;d[i]=Math.floor((47+checker*13)*fog);d[i+1]=Math.floor((43+checker*12)*fog);d[i+2]=Math.floor((36+checker*10)*fog);d[i+3]=255}}

