 function update(dt){if(!running)return;elapsed+=dt;fireCooldown=Math.max(0,fireCooldown-dt);shot=Math.max(0,shot-dt*4);toastTimer=Math.max(0,toastTimer-dt);document.getElementById('clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){let take=Math.min(12-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;updateAmmo()}}let speed=(keys.has('shift')?3.5:2.5)*dt,turn=1.9*dt;if(keys.has('arrowleft'))player.a-=turn;if(keys.has('arrowright'))player.a+=turn;let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup')){dx+=Math.cos(player.a)*speed;dy+=Math.sin(player.a)*speed}if(keys.has('s')||keys.has('arrowdown')){dx-=Math.cos(player.a)*speed;dy-=Math.sin(player.a)*speed}if(keys.has('a')){dx+=Math.cos(player.a-Math.PI/2)*speed;dy+=Math.sin(player.a-Math.PI/2)*speed}if(keys.has('d')){dx+=Math.cos(player.a+Math.PI/2)*speed;dy+=Math.sin(player.a+Math.PI/2)*speed}movePlayer(dx,dy);for(let e of enemies){if(!e.alive)continue;let d=Math.hypot(player.x-e.x,player.y-e.y);if(d>1.1){let vx=(player.x-e.x)/d*dt*.55,vy=(player.y-e.y)/d*dt*.55;if(!cell(e.x+vx,e.y))e.x+=vx;if(!cell(e.x,e.y+vy))e.y+=vy}else{e.attack-=dt;if(e.attack<=0){player.hp=Math.max(0,player.hp-8);e.attack=1.1;updateHealth();if(player.hp<=0)endGame(false)}}}if(enemies.every(e=>!e.alive)){if(toastTimer<=0){toastTimer=2;document.getElementById('toast').classList.add('show');setTimeout(()=>document.getElementById('toast').classList.remove('show'),900);setTimeout(()=>{if(running&&enemies.every(e=>!e.alive)){wave++;spawnWave()}},1400)}}}
 function movePlayer(dx,dy){if(!cell(player.x+dx*1.5,player.y))player.x+=dx;if(!cell(player.x,player.y+dy*1.5))player.y+=dy}
 function fire(){if(!running||fireCooldown>0||reloadTimer>0)return;if(player.ammo<=0){reload();return}player.ammo--;updateAmmo();fireCooldown=.32;shot=1;document.getElementById('weapon').classList.add('fire');setTimeout(()=>document.getElementById('weapon').classList.remove('fire'),90);document.getElementById('hitflash').classList.remove('flash');void document.getElementById('hitflash').offsetWidth;document.getElementById('hitflash').classList.add('flash');let target=null,best=.17;for(let e of enemies){if(!e.alive)continue;let a=Math.atan2(e.y-player.y,e.x-player.x)-player.a;while(a>Math.PI)a-=2*Math.PI;while(a< -Math.PI)a+=2*Math.PI;let dist=Math.hypot(e.x-player.x,e.y-player.y);if(Math.abs(a)<best&&dist<depth[Math.round(W/2+Math.tan(a)*W*.66)]&&dist<9){target=e;best=Math.abs(a)}}if(target){target.hp--;if(target.hp<=0){target.alive=false;kills++;updateKills()}}}
 function reload(){if(reloadTimer>0||player.ammo===12||player.reserve<=0)return;reloadTimer=1.1;toast('RELOADING',800)}function toast(text,ms){let t=document.getElementById('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>{if(t.textContent===text)t.classList.remove('show')},ms)}function updateAmmo(){document.getElementById('ammoNum').textContent=player.ammo}function updateHealth(){document.getElementById('healthNum').textContent=player.hp;document.getElementById('healthFill').style.width=player.hp+'%'}function updateKills(){document.getElementById('kills').textContent=`HOSTILES ${kills} / ${kills+enemies.filter(e=>e.alive).length}`}
-function start(){if(dead){player={x:2.5,y:2.5,a:0,hp:100,ammo:12,reserve:48};wave=1;kills=0;elapsed=0;dead=false;updateHealth();updateAmmo()}spawnWave();running=true;document.getElementById('overlay').style.display='none';canvas.requestPointerLock?.();last=performance.now()}
+function start(){if(dead){player={x:1.5,y:1.5,a:0,hp:100,ammo:12,reserve:48};wave=1;kills=0;elapsed=0;dead=false;updateHealth();updateAmmo()}spawnWave();running=true;document.getElementById('overlay').style.display='none';canvas.requestPointerLock?.();last=performance.now()}
 function endGame(win){running=false;dead=!win;document.exitPointerLock?.();let card=document.querySelector('.card');card.innerHTML=`<div class="eyebrow">[ UAC // ${win?'MISSION COMPLETE':'SIGNAL LOST'} ]</div><h1 class="title">${win?'SECTOR':'YOU ARE'}<br><span>${win?'CLEARED':'DEAD'}</span></h1><div class="subtitle">${win?'THE COMPLEX IS QUIET. FOR NOW.':'THE MAZE CLAIMS ANOTHER.'}</div><p class="copy">WAVE ${String(wave).padStart(2,'0')} &nbsp; / &nbsp; HOSTILES ELIMINATED: ${kills} &nbsp; / &nbsp; TIME: ${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}</p><button class="btn" id="startBtn">${win?'PLAY AGAIN':'TRY AGAIN'}</button><span class="footnote">YOU CAN DO BETTER.</span>`;document.getElementById('startBtn').onclick=start;document.getElementById('overlay').style.display='flex'}
 function loop(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(loop)}
 document.getElementById('startBtn').addEventListener('click',start);window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys.add(k);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '){fire()}if(k==='r')reload();if(k==='escape'&&running&&document.pointerLockElement!==canvas){running=false;document.getElementById('overlay').style.display='flex'}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());canvas.addEventListener('click',()=>{if(running&&!document.pointerLockElement)canvas.requestPointerLock?.();fire()});document.addEventListener('mousemove',e=>{if(running&&document.pointerLockElement===canvas)player.a+=e.movementX*.0025});document.addEventListener('pointerlockchange',()=>{if(running&&!document.pointerLockElement){running=false;document.getElementById('overlay').style.display='flex'}});
 for(let b of document.querySelectorAll('.touchbtn')){let key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key)});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(key)))}document.getElementById('fireTouch').addEventListener('pointerdown',e=>{e.preventDefault();fire()});let touchX=null;canvas.addEventListener('touchstart',e=>{touchX=e.touches[0].clientX},{passive:true});canvas.addEventListener('touchmove',e=>{if(touchX!==null){let x=e.touches[0].clientX;player.a+=(x-touchX)*.009;touchX=x}},{passive:true});canvas.addEventListener('touchend',()=>touchX=null);requestAnimationFrame(loop);

